COLDWAR_SYR_campaign_weekly = {
    if = { limit = { original_tag = SYR IMP_is_1970_scenario = yes } COLDWAR_SYR_update_operation_costs = yes }
    if = {
        limit = { original_tag = SYR IMP_is_1970_scenario = yes OR = { has_country_flag = COLDWAR_SYR_operational_mandate has_idea = COLDWAR_SYR_war_reserve_readiness has_idea = COLDWAR_SYR_war_supply_preparation has_idea = COLDWAR_SYR_war_joint_planning has_idea = COLDWAR_SYR_war_medical_service has_idea = COLDWAR_SYR_war_short_window has_idea = COLDWAR_SYR_war_sustained_window } }
        if = {
            limit = {
                OR = {
                    NOT = { country_exists = ISR }
                    NOT = { has_country_flag = COLDWAR_SYR_operational_mandate }
                    is_in_faction_with = ISR
                    NOT = { ISR = { controls_state = 587 } }
                    AND = { NOT = { has_war_with = ISR } NOT = { has_wargoal_against = ISR } }
                }
            }
            COLDWAR_SYR_clear_campaign_effects = yes
        }
    }
}
# NEW scenario-guarded Syria on_weekly hook calls COLDWAR_SYR_campaign_weekly.
# It never touches COLDWAR_SYR_war_bridge_credit or debt, and never grants a war goal.
# An unused funded appropriation WITHOUT an active mandate/idea survives until its own expiry.

